package tv.plus.pro.home;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.provider.*;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 int bg=0xff0b0d23, purple=0xff8437e9, white=0xfff6f5ff; LinearLayout content,nav; boolean wide; String section="home";
 int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 GradientDrawable shape(int a,int b,int radius){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});d.setCornerRadius(dp(radius));d.setStroke(dp(1),0x556e64b3);return d;}
 TextView text(String s,int size,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextColor(white);v.setTextSize(size);v.setGravity(Gravity.CENTER_VERTICAL);if(bold)v.setTypeface(null,1);return v;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void gap(LinearLayout p,int n){Space s=new Space(this);p.addView(s,new LinearLayout.LayoutParams(1,dp(n)));}
 void heading(String s){TextView t=text(s,20,true);content.addView(t);gap(content,12);}
 void tile(LinearLayout parent,String title,String subtitle,Runnable action){LinearLayout box=column();box.setPadding(dp(14),dp(12),dp(14),dp(12));box.setBackground(shape(0xff293665,0xff39205f,17));box.setFocusable(true);TextView a=text(title,15,true);box.addView(a);if(subtitle!=null){TextView b=text(subtitle,11,false);b.setTextColor(0xffc7c2df);box.addView(b);}box.setOnClickListener(v->action.run());box.setOnFocusChangeListener((v,f)->{box.setBackground(f?shape(0xff7432df,0xffaf3fe9,17):shape(0xff293665,0xff39205f,17));});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(4),dp(4),dp(4),dp(4));parent.addView(box,p);}
 void rowTiles(String[][] items,Runnable[] actions){LinearLayout row=new LinearLayout(this);row.setOrientation(wide?0:1);content.addView(row);for(int i=0;i<items.length;i++){final int j=i;LinearLayout holder=column();row.addView(holder,new LinearLayout.LayoutParams(wide?0:-1,-2,wide?1:0));tile(holder,items[i][0],items[i][1],actions[j]);}}
 void navItem(String name,String key){LinearLayout b=new LinearLayout(this);b.setGravity(Gravity.CENTER);b.setOrientation(0);b.setPadding(dp(6),dp(8),dp(6),dp(8));b.setBackground(shape(section.equals(key)?0xff8137e9:0xff161b3d,section.equals(key)?0xff4e22a5:0xff1b1944,14));int id=key.equals("home")?tv.plus.pro.unified.R.drawable.home:key.equals("apps")?tv.plus.pro.unified.R.drawable.apps:key.equals("settings")?tv.plus.pro.unified.R.drawable.settings:key.equals("files")?tv.plus.pro.unified.R.drawable.files:key.equals("gallery")?tv.plus.pro.unified.R.drawable.gallery:tv.plus.pro.unified.R.drawable.volume;ImageView iv=new ImageView(this);iv.setImageResource(id);b.addView(iv,new LinearLayout.LayoutParams(dp(18),dp(18)));TextView t=text(" "+name,wide?12:11,false);b.addView(t);b.setFocusable(true);b.setOnClickListener(v->render(key));b.setOnFocusChangeListener((v,focused)->b.setBackground(shape(focused?0xffa64af1:section.equals(key)?0xff8137e9:0xff161b3d,focused?0xff6427d1:0xff1b1944,14)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(2),dp(2),dp(2),dp(2));nav.addView(b,p);}
 void render(String key){section=key;wide=getResources().getConfiguration().screenWidthDp>=600;LinearLayout base=column();base.setBackground(shape(bg,0xff151039,0));base.setPadding(dp(12),dp(10),dp(12),dp(10));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);ImageView mark=new ImageView(this);mark.setImageResource(tv.plus.pro.unified.R.drawable.icon);top.addView(mark,new LinearLayout.LayoutParams(dp(32),dp(32)));TextView logo=text("TV+",wide?25:21,true);top.addView(logo);TextView current=text("   "+(key.equals("home")?"":key.equals("settings")?"Ayarlar":key.equals("files")?"Dosyalar":key.equals("gallery")?"Galeri":key.equals("sound")?"Ses":"Uygulamalar"),wide?16:12,false);top.addView(current);Space spacer=new Space(this);top.addView(spacer,new LinearLayout.LayoutParams(0,1,1));TextView status=text("●  "+new java.text.SimpleDateFormat("HH:mm",java.util.Locale.getDefault()).format(new java.util.Date()),wide?14:11,false);top.addView(status);base.addView(top);gap(base,8);
 LinearLayout shell=new LinearLayout(this);shell.setOrientation(wide?0:1);
 nav=column();nav.setOrientation(0);navItem("Ana Ekran","home");navItem("Uygulamalar","apps");navItem("Ayarlar","settings");navItem("Dosyalar","files");navItem("Galeri","gallery");navItem("Ses","sound");base.addView(nav,new LinearLayout.LayoutParams(-1,-2));base.addView(shell,new LinearLayout.LayoutParams(-1,0,1));
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=column();content.setPadding(dp(12),dp(8),dp(12),dp(20));scroll.addView(content);shell.addView(scroll,new LinearLayout.LayoutParams(-1,-1));setContentView(base);
 if(key.equals("home"))home();else if(key.equals("apps"))apps();else if(key.equals("settings"))settings();else if(key.equals("files"))files();else if(key.equals("gallery"))gallery();else sound();
 }
 void home(){LinearLayout hero=column();hero.setPadding(dp(22),dp(16),dp(22),dp(16));hero.setBackground(shape(0xff184cc1,0xff8e27db,22));TextView big=text("TV+   ▶",26,true);hero.addView(big);TextView subtitle=text("Yeni nesil TV deneyimi",16,true);hero.addView(subtitle);TextView detail=text("Uygulamalar, içerikler ve daha fazlası",12,false);hero.addView(detail);hero.setFocusable(true);hero.setOnClickListener(v->render("apps"));content.addView(hero);gap(content,9);heading("Hızlı Uygulamalar");appsPreview();gap(content,8);heading("Son Kullanılanlar ve Kısayollar");rowTiles(new String[][]{{"▣ Dosyalar","Dosyaları aç"},{"▧ Galeri","Fotoğraflar"},{"⚙ Ayarlar","Cihaz ayarları"}},new Runnable[]{()->render("files"),()->render("gallery"),()->render("settings")});}
 void appsPreview(){appGrid(true);}
 void apps(){heading("Yüklü Uygulamalar");appGrid(false);}
 void appGrid(boolean preview){PackageManager pm=getPackageManager();java.util.LinkedHashMap<String,ResolveInfo> found=new java.util.LinkedHashMap<>();for(String cat:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER}){Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(cat);for(ResolveInfo r:pm.queryIntentActivities(q,0)){String pkg=r.activityInfo.packageName;if(!pkg.equals(getPackageName())&&!found.containsKey(pkg))found.put(pkg,r);}}if(found.isEmpty()){tile(content,"Uygulama bulunamadı","Yüklü uygulama listesi boş",()->{});return;}int cols=wide?8:3;LinearLayout line=null;int index=0;for(ResolveInfo r:found.values()){if(preview&&index>=8)break;if(index%cols==0){line=new LinearLayout(this);line.setOrientation(0);content.addView(line);}final String pkg=r.activityInfo.packageName;LinearLayout cell=column();cell.setGravity(Gravity.CENTER);cell.setPadding(dp(6),dp(12),dp(6),dp(10));cell.setBackground(shape(0xff18244a,0xff33205d,15));cell.setFocusable(true);cell.setOnFocusChangeListener((v,focus)->cell.setBackground(focus?shape(0xff7336df,0xffad4ded,15):shape(0xff18244a,0xff33205d,15)));ImageView icon=new ImageView(this);try{icon.setImageDrawable(r.loadIcon(pm));}catch(Exception ignored){}cell.addView(icon,new LinearLayout.LayoutParams(dp(34),dp(34)));TextView label=text(r.loadLabel(pm).toString(),12,true);label.setGravity(Gravity.CENTER);label.setMaxLines(1);label.setEllipsize(android.text.TextUtils.TruncateAt.END);cell.addView(label);cell.setOnClickListener(v->launch(pkg));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(83),1);lp.setMargins(dp(4),dp(5),dp(4),dp(5));line.addView(cell,lp);index++;}if(line!=null&&index%cols!=0){for(int i=index%cols;i<cols;i++){line.addView(new Space(this),new LinearLayout.LayoutParams(0,dp(1),1));}}}
 void appList(boolean preview){PackageManager pm=getPackageManager();HashSet<String> seen=new HashSet<>();int count=0;for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER}){Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(category);for(ResolveInfo r:pm.queryIntentActivities(q,0)){String id=r.activityInfo.packageName+"/"+r.activityInfo.name;if(!seen.add(id)||r.activityInfo.packageName.equals(getPackageName()))continue;final String pkg=r.activityInfo.packageName;tile(content,"▣ "+r.loadLabel(pm),"Uygulamayı aç",()->launch(pkg));if(preview&&++count>=6)return;}}if(count==0)tile(content,"Uygulama bulunamadı","Cihaz uygulamaları listelenemiyor",()->{});}
 void launch(String pkg){try{PackageManager pm=getPackageManager();Intent i=pm.getLeanbackLaunchIntentForPackage(pkg);if(i==null)i=pm.getLaunchIntentForPackage(pkg);if(i==null)throw new Exception("Başlatıcı bulunamadı");startActivity(i);}catch(Exception e){alert("Uygulama açılamadı: "+e.getMessage());}}
 void settings(){heading("Genel Ayarlar");rowTiles(new String[][]{{"◉ Ağ ve İnternet","Wi-Fi ve bağlantı"},{"ᛒ Bluetooth","Cihazları eşleştir"}},new Runnable[]{()->setting(Settings.ACTION_WIFI_SETTINGS),()->setting(Settings.ACTION_BLUETOOTH_SETTINGS)});rowTiles(new String[][]{{"▣ Görüntü","Ekran ayarları"},{"♫ Ses","Ses kontrolleri"}},new Runnable[]{()->setting(Settings.ACTION_DISPLAY_SETTINGS),()->render("sound")});rowTiles(new String[][]{{"▦ Uygulamalar","Uygulama yönetimi"},{"▤ Depolama","Depolama bilgisi"}},new Runnable[]{()->setting(Settings.ACTION_APPLICATION_SETTINGS),()->setting(Settings.ACTION_INTERNAL_STORAGE_SETTINGS)});rowTiles(new String[][]{{"ⓘ Sistem","Cihaz bilgisi"},{"⚙ Gelişmiş Ayarlar","Orijinal Android ayarları"}},new Runnable[]{()->setting(Settings.ACTION_DEVICE_INFO_SETTINGS),()->setting(Settings.ACTION_SETTINGS)});}
 void setting(String action){try{startActivity(new Intent(action));}catch(Exception e){try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception x){alert(x.toString());}}}
 void files(){heading("Depolama");android.os.StatFs stat=new android.os.StatFs(android.os.Environment.getExternalStorageDirectory().getPath());long total=stat.getTotalBytes(),used=total-stat.getAvailableBytes();tile(content,"▣ Ana Depolama",String.format(java.util.Locale.getDefault(),"%.1f GB / %.1f GB",used/1e9,total/1e9),()->tree());heading("Klasörler ve Dosyalar");rowTiles(new String[][]{{"📁 Klasör Seç","USB / dahili depolama"},{"▤ Dosya Aç","Belge ve arşiv"}},new Runnable[]{()->tree(),()->pick("*/*",10)});rowTiles(new String[][]{{"▧ Resimler","Fotoğraflar"},{"▶ Videolar","Video dosyaları"}},new Runnable[]{()->pick("image/*",11),()->pick("video/*",12)});}
 void gallery(){heading("Tüm Fotoğraflar");tile(content,"▧ Fotoğrafları Görüntüle","Cihazdan fotoğraf seç",()->pick("image/*",11));tile(content,"▶ Videolar","Cihazdan video seç",()->pick("video/*",12));}
 void sound(){heading("Ses Kontrolü");android.media.AudioManager a=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);int max=a.getStreamMaxVolume(3);SeekBar bar=new SeekBar(this);bar.setMax(max);bar.setProgress(a.getStreamVolume(3));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){if(user)a.setStreamVolume(3,p,0);}});content.addView(bar);tile(content,"＋ Sesi Artır",null,()->{a.adjustStreamVolume(3,1,0);bar.setProgress(a.getStreamVolume(3));});tile(content,"－ Sesi Azalt",null,()->{a.adjustStreamVolume(3,-1,0);bar.setProgress(a.getStreamVolume(3));});}
 void tree(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),20);}catch(Exception e){alert(e.toString());}}
 void pick(String type,int req){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType(type);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,req);}catch(Exception e){alert(e.toString());}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(req==20){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);alert("Klasör seçildi: "+uri);return;}try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(uri,getContentResolver().getType(uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){alert("Dosya açılamadı: "+e.getMessage());}}
 void alert(String msg){new AlertDialog.Builder(this).setMessage(msg).setPositiveButton("Tamam",null).show();}
 @Override public void onCreate(Bundle b){super.onCreate(b);render("home");}
 @Override public void onBackPressed(){if(!section.equals("home"))render("home");else super.onBackPressed();}
}